import React, { useEffect, useState, useRef } from 'react';
import Chart from 'chart.js/auto';
import Select from 'react-select';
import api from '../utils/api';

const monthOptions = [
    { value: 0, label: 'January' },
    { value: 1, label: 'February' },
    { value: 2, label: 'March' },
    { value: 3, label: 'April' },
    { value: 4, label: 'May' },
    { value: 5, label: 'June' },
    { value: 6, label: 'July' },
    { value: 7, label: 'August' },
    { value: 8, label: 'September' },
    { value: 9, label: 'October' },
    { value: 10, label: 'November' },
    { value: 11, label: 'December' }
];

const ChartComponent = () => {
    const [data, setData] = useState(null);
    const [error, setError] = useState(null);
    const [aircraftOptions, setAircraftOptions] = useState([]);
    const [selectedAircrafts, setSelectedAircrafts] = useState([]);
    const [yearOptions, setYearOptions] = useState([]);
    const [selectedYears, setSelectedYears] = useState([]);
    const [selectedMonths, setSelectedMonths] = useState([]);
    const chartRef = useRef(null);

    useEffect(() => {
        const fetchData = async () => {
            try {
                const result = await api.getData();
                setData(result.data);

                const uniqueAircrafts = [...new Set(result.data.invoices.map(item => item.Aircraft))];
                setAircraftOptions(uniqueAircrafts.map(aircraft => ({ value: aircraft, label: aircraft })));

                const uniqueYears = [...new Set(result.data.invoices.map(item => new Date(item['Trip start Z']).getFullYear()))];
                setYearOptions(uniqueYears.sort().map(year => ({ value: year, label: year.toString() })));

            } catch (error) {
                setError('Error fetching data: ' + error.message);
            }
        };

        fetchData();
    }, []);

    useEffect(() => {
        if (!data) return;

        const filteredInvoices = data.invoices.filter(invoice => {
            return invoice.Status === 'Invoiced' &&
                   (selectedAircrafts.length === 0 || selectedAircrafts.includes(invoice.Aircraft)) &&
                   (selectedYears.length === 0 || selectedYears.includes(new Date(invoice['Trip start Z']).getFullYear())) &&
                   (selectedMonths.length === 0 || selectedMonths.includes(new Date(invoice['Trip start Z']).getMonth()));
        });

        const revenuePerHour = {};
        filteredInvoices.forEach(invoice => {
            const matchingFlights = data.loggedFlights.filter(flight => flight.Trip === invoice.Trip && flight.Aircraft === invoice.Aircraft);
            const totalFlightHours = matchingFlights.reduce((acc, cur) => acc + parseFloat(cur['Flight hrs']), 0);
            revenuePerHour[invoice.Aircraft] = ((revenuePerHour[invoice.Aircraft] || 0) + parseFloat(invoice.Price)) / (totalFlightHours || 1);
        });

        const labels = Object.keys(revenuePerHour);
        const dataPoints = labels.map(label => revenuePerHour[label]);

        const ctx = chartRef.current.getContext('2d');
        if (chartRef.current) {
            chartRef.current.destroy();
        }
        chartRef.current = new Chart(ctx, {
            type: 'bar',
            data: {
                labels,
                datasets: [{
                    label: 'Revenue per Hour',
                    data: dataPoints,
                    backgroundColor: 'rgba(75, 192, 192, 0.2)',
                    borderColor: 'rgba(75, 192, 192, 1)',
                    borderWidth: 1
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    y: {
                        beginAtZero: true
                    }
                }
            }
        });
    }, [data, selectedAircrafts, selectedYears, selectedMonths]);

    if (error) return <div>{error}</div>;

    return (
        <div style={{ width: '80%', margin: 'auto' }}>
            <h1>Revenue per Hour of Aircrafts</h1>
            <Select
                isMulti
                options={aircraftOptions}
                onChange={selectedOpts => setSelectedAircrafts(selectedOpts.map(opt => opt.value))}
                placeholder="Select Aircrafts"
            />
            <Select
                isMulti
                options={yearOptions}
                onChange={selectedOpts => setSelectedYears(selectedOpts.map(opt => opt.value))}
                placeholder="Select Years"
            />
            <Select
                isMulti
                options={monthOptions}
                onChange={selectedOpts => setSelectedMonths(selectedOpts.map(opt => opt.value))}
                placeholder="Select Months"
            />
            <div style={{ height: '500px' }}>
                <canvas ref={chartRef}></canvas>
            </div>
        </div>
    );
};

export default ChartComponent;
